r.append(R(7315331,"चेडर और लीक पैनकेक","आज कुछ अलग नाश्ता आज़माएँ, जैसे ये झटपट और आसान नमकीन पैनकेक।","4","143 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","1 लीक, बारीक कटा हुआ","1 अंडा, फेंटा हुआ","150 मिलीलीटर सेमी-स्किम्ड दूध","100 ग्राम साबुत गेहूँ का आटा","50 ग्राम कम वसा वाला पुराना चेडर चीज़, बारीक चौकोर कटा हुआ","चुटकी भर काली मिर्च"],
["धीमी से मध्यम आँच पर सॉसपैन में 1 छोटा चम्मच तेल डालें, फिर लीक डालें। 3-4 मिनट तक नियमित रूप से चलाते हुए पकाएँ जब तक लीक नरम न हो जाए, फिर आँच से उतार लें।","अंडे को दूध में फेंटें, फिर आटे को एक कटोरे में डालें और धीरे-धीरे दूध का मिश्रण चिकना होने तक मिलाएँ। इसके बाद, चीज़ और लीक डालें। अच्छी तरह मिलाएँ। काली मिर्च डालें।","नॉन-स्टिक पैन गरम करें। बचा हुआ तेल डालें और किचन पेपर से उसे पैन में चारों ओर फैलाएँ, फिर मिश्रण का 1 बड़ा चम्मच डालें।","2 मिनट तक पकाएँ, फिर स्पैचुला से पलटें और दूसरी तरफ़ एक-दो मिनट और पकाएँ। पैनकेक लगभग 8 सेमी व्यास के और केवल 3-4 मिमी मोटे होने चाहिए। आप एक बड़े पैन में एक साथ 2 या 3 पकाने में सक्षम होने चाहिए।"],
["बराबर पकने के लिए सामग्री को बारीक काटना चाहिए।","अतिरिक्त स्वाद के लिए चाइव्स, तुलसी या टैरागन जैसी ताज़ी जड़ी-बूटियाँ डालें।",FV(0)]))
r.append(R(7320020,"रास्पबेरी फ्रोज़न योगर्ट","एक ताज़ा खट्टी-मीठी मिठाई, जो गर्मियों में मेहमानों के लिए आदर्श है।","11","100 ग्राम",
["300 ग्राम ताज़ी रास्पबेरी","500 ग्राम ग्रीक दही","50 ग्राम बारीक पिसी चीनी (कैस्टर शुगर)"],
["आधी रास्पबेरी को ब्लेंडर या फ़ूड प्रोसेसर में डालें और प्यूरी बनाएँ।","दही और चीनी को मिलाएँ और फ़्रीज़र में रखने योग्य डिब्बे में डालें, 1 घंटे के लिए फ्रीज़ करें, अच्छी तरह चलाएँ फिर बची हुई रास्पबेरी और रास्पबेरी प्यूरी को हल्के से मिलाएँ।","30 मिनट के लिए वापस फ़्रीज़र में रखें, फिर कांटे से दोबारा मिलाएँ और वापस फ़्रीज़र में रखें। जमने तक 30 मिनट और फ्रीज़ करें।","परोसने से 5 मिनट पहले फ़्रीज़र से निकालें"],
["आप इस तरीके से ज़्यादातर फलों का उपयोग कर सकते हैं, आम, ब्लूबेरी, स्ट्रॉबेरी या नेक्टरीन आज़माएँ।","अगर परोसने के लिए आइसक्रीम स्कूप इस्तेमाल कर रहे हैं, तो आसानी से परोसने के लिए हर स्कूप के बीच उसे गरम पानी में डुबोएँ।"]))
r.append(R(7320245,"जड़ी-बूटी वाले भरवाँ बैंगन","यह रेसिपी एक दिलचस्प हल्का शाकाहारी व्यंजन या स्टार्टर बनाती है।","4","327 ग्राम",
["100 ग्राम बुलगर गेहूँ","2 मध्यम बैंगन, लंबाई में आधे कटे हुए (वज़न 700 ग्राम)","2 बड़े चम्मच जैतून का तेल","1 प्याज़, बारीक कटा हुआ","1 लहसुन की फांक, कुचली हुई","1 छोटा चम्मच पिसा जीरा","1 छोटा चम्मच पिसा धनिया","25 ग्राम बिना बीज वाली किशमिश","2 बड़े चम्मच ताज़ा धनिया, कटा हुआ","2 बड़े चम्मच ताज़ा पुदीना, कटा हुआ","2 बड़े चम्मच पार्मेसन की कतरनें"],
["ओवन को 200ºC/गैस 6 पर पहले से गरम करें। बुलगर गेहूँ को एक बड़े कटोरे में डालें, उस पर 600 मिलीलीटर उबलता पानी डालें और 30 मिनट तक या नरम होने तक भीगने दें।","बैंगन के आधे हिस्सों को बेकिंग ट्रे पर छिलके वाली तरफ़ नीचे करके रखें, और कटी हुई सतह पर आधा जैतून का तेल लगाएँ। 25-30 मिनट तक या सुनहरा होने तक बेक करें।","ओवन से निकालें, गूदा खुरचकर निकालें और मोटा काट लें।","इस बीच, बुलगर गेहूँ से अतिरिक्त तरल निकाल दें। एक पैन में बचा हुआ तेल गरम करें और प्याज़ और लहसुन को 2-3 मिनट तक नरम होने तक भूनें।","पिसा जीरा और धनिया डालें और 1 मिनट और भूनते रहें।","पार्मेसन को छोड़कर बाकी सामग्री डालें, जिसमें भीगा हुआ बुलगर गेहूँ और बैंगन का गूदा शामिल है।","गरम करें, फिर मिश्रण को बैंगन के खोलों में बाँट दें। वापस ओवन में रखें और 10-15 मिनट तक पकाएँ, जब तक कि ऊपरी परत सुनहरी न हो जाए। परोसते समय पार्मेसन की कतरनें छिड़कें।"],
["ग्लूटेन-मुक्त संस्करण के लिए बुलगर गेहूँ की जगह क्विनोआ इस्तेमाल करें।","आप पार्मेसन की जगह थोड़ा डेयरी-मुक्त चीज़ भी डाल सकते हैं ताकि यह शाकाहारी और वीगन व्यंजन बन जाए।",FV(2)]))
r.append(R(7323191,"फलों से भरे सनडे","बच्चों के बनाने के लिए एक बढ़िया व्यंजन। आपके पास उपलब्ध किसी भी प्रकार के फल का उपयोग करें, जिसमें डिब्बाबंद या पिघलाए हुए जमे फल भी शामिल हैं।","3","205 ग्राम",
["2 मेरिंग्यू नेस्ट, मोटे कुचले हुए, कुल वज़न 25 ग्राम","1 केला, कटा हुआ","1 कीवी, छिली और कटी हुई","1 पपीता, छीला, बीज निकाला हुआ और कटा हुआ","2 पैशन फ्रूट का गूदा","200 ग्राम का डिब्बा लगभग वसा-रहित फ्रोमाज फ्रे"],
["3 लंबे गिलासों की तली में थोड़ा मेरिंग्यू रखें। हर गिलास में थोड़ा केला, कीवी, पपीता और पैशन फ्रूट डालें।","फलों पर थोड़ा फ्रोमाज फ्रे चम्मच से डालें।","सामग्री की परतें तब तक लगाते रहें जब तक सब इस्तेमाल न हो जाए। तुरंत परोसें।"],
["यह स्ट्रॉबेरी, रास्पबेरी और ब्लैकबेरी जैसी बेरियों के चयन के साथ भी बढ़िया बनता है।"]))
r.append(R(7325527,"कूसकूस के साथ शकरकंद, छोले और गाजर का टैगीन","मीठी और नरम सब्ज़ियाँ मोरक्को के मसालों के मिश्रण के साथ मिलकर एक रसीला, आरामदायक स्ट्यू बनाती हैं।","4","424 ग्राम",
["टैगीन के लिए: 2 छोटे चम्मच जैतून का तेल","1 प्याज़, बारीक कटा हुआ","2 लहसुन की फांकें, बारीक कटी हुई","2 छोटे चम्मच रास-एल-हानूत, मोरक्को का मसाला मिश्रण","2 छोटे चम्मच स्मोक्ड पेपरिका","1/2 छोटा चम्मच पिसी दालचीनी","1 शकरकंद, छीली और चौकोर कटी हुई (250 ग्राम)","4 बड़ी गाजर, छीली और चौकोर कटी हुई (500 ग्राम)","200 ग्राम/7 औंस का डिब्बा छोले, छाने और धोए हुए","500 मिलीलीटर/18 फ्लूइड औंस पानी","400 ग्राम/14 औंस डिब्बाबंद कटे हुए टमाटर","1 बड़ा चम्मच पिसे बादाम","ताज़ी पिसी काली मिर्च","परोसने के लिए: 120 ग्राम/6 औंस कूसकूस","2 बड़े चम्मच फ़्लैट-लीफ़ अजमोद (पार्सले), कटा हुआ"],
["टैगीन के लिए: एक बड़े कैसरोल डिश या टैगीन को मध्यम आँच पर रखकर उसमें जैतून का तेल गरम होने तक गरम करें।","प्याज़ और लहसुन डालें, लगभग 5 मिनट तक नरम होने तक पकाएँ और फिर पिसे मसाले डालें।","शकरकंद, गाजर, पानी और कटे टमाटर मिलाने से पहले 2 मिनट और पकाएँ।","उबाल लाएँ और फिर आँच को हल्की, स्थिर उबाल पर कम करें जब तक कि सब्ज़ियाँ बहुत नरम न हो जाएँ और सॉस गाढ़ा न हो जाए, लगभग 25-30 मिनट। समय-समय पर चलाते रहें।","पिसे बादाम और छोले मिलाएँ और स्वाद अनुसार थोड़ी ताज़ी पिसी काली मिर्च डालें। ढककर आँच से उतारकर गरम रखें।","परोसने के लिए: एक सॉसपैन में 375 मिलीलीटर पानी उबालें। उबल जाने पर, आँच से उतारें और कूसकूस मिलाएँ।","कसकर ढक्कन से ढक दें और रखा रहने दें। 10 मिनट बाद, दानों को अलग करने के लिए कूसकूस को फुला लें।","प्लेटों में बाँटें और ऊपर से टैगीन डालें। कटा हुआ अजमोद छिड़कें।"],
["इस व्यंजन में शकरकंद की जगह बटरनट स्क्वैश या कद्दू एक अच्छा कम कार्बोहाइड्रेट वाला विकल्प होगा।",FV(3)]))
r.append(R(7328009,"भुना चिकोरी और संतरे का सलाद","ताज़े स्वादों वाला एक अलग, सेहतमंद सलाद।","4","157 ग्राम",
["4 चिकोरी, लंबाई में आधी कटी हुई","1 संतरे का कद्दूकस किया हुआ छिलका और रस","1 छोटा चम्मच जैतून का तेल","1 छोटा चम्मच ताज़ा थाइम या चुटकी भर सूखा","ताज़ी पिसी काली मिर्च","2 संतरे, फांकों में अलग किए हुए","2 छोटे चम्मच संतरे का ज़ेस्ट, सजाने के लिए"],
["ओवन को 200ºC/गैस 6 पर पहले से गरम करें। चिकोरी को ओवन-प्रूफ़ डिश में रखें। संतरे का छिलका और रस, तेल और थाइम को मिलाएँ। चिकोरी पर छिड़कें फिर भरपूर काली मिर्च डालें।","25-30 मिनट तक पकाएँ, जब तक कि नरम न हो जाए और जलने के निशान न दिखने लगें। संतरे की फांकों के साथ उछालकर मिलाएँ और पकाने के किसी भी तरल और संतरे के ज़ेस्ट के साथ छिड़ककर परोसें। परोसने से पहले थोड़ा ठंडा करें या फ्रिज में रखें।"],
["चिकोरी का स्वाद थोड़ा कड़वा होता है जो संतरे की मिठास का पूरक है।","लाल चिकोरी देखें जिसका स्वाद इसी तरह का होता है और रंग बढ़िया होता है।",FV(2)]))
r.append(R(7328847,"चिकन, कॉर्न और दाल का पुलाव","भरपूर प्रोटीन और सेहतमंद सब्ज़ियों से भरा एक संतुलित भोजन।","2","466 ग्राम",
["1 छोटा चम्मच रेपसीड तेल","1 बड़ा प्याज़, कटा हुआ","250 ग्राम चिकन ब्रेस्ट, टुकड़ों में कटा हुआ","1 लाल शिमला मिर्च, कटी हुई","25 ग्राम सुल्ताना (सुनहरी किशमिश)","1 छोटा चम्मच जीरा","एक अच्छी चुटकी सफ़ेद मिर्च","2 लहसुन की फांकें, कुचली हुई","400 ग्राम डिब्बाबंद हरी दाल, छनी हुई","160 ग्राम स्वीटकॉर्न, जमा हुआ","1 बड़ा चम्मच ताज़ा अजमोद (पार्सले), कटा हुआ","परोसने के लिए सलाद"],
["पैन में रेपसीड तेल गरम करें और प्याज़ डालें। तीन मिनट पकाएँ, जब तक कि प्याज़ बस भूरा होने न लगे, फिर चिकन ब्रेस्ट के टुकड़े डालें। 3-4 मिनट चलाएँ।","इसके बाद, शिमला मिर्च, सुल्ताना, जीरा, सफ़ेद मिर्च और कुचला लहसुन पैन में डालें। अच्छी तरह मिलाएँ और नियमित रूप से चलाते हुए 4-5 मिनट तक पकाएँ।","दाल को जमे हुए स्वीटकॉर्न के साथ पैन में डालें। 3 मिनट तक गरम करें।","अजमोद मिलाएँ और सलाद के साथ परोसें।"],
["एक स्वादिष्ट शाकाहारी विकल्प के लिए चिकन की जगह टोफू इस्तेमाल करें।",FV(4)]))
r.append(R(7332922,"बीफ़बर्गर","दुबला बीफ़ कीमा इस्तेमाल करने से यह बर्गर एक ज़्यादा सेहतमंद विकल्प बन जाता है।","6","272 ग्राम",
["साबुत गेहूँ की ब्रेड का 1 स्लाइस","एक अच्छी चुटकी सफ़ेद मिर्च","1-2 लहसुन की फांकें, कुचली हुई","1 मध्यम अंडा, हल्का फेंटा हुआ","100 ग्राम प्याज़, बारीक कद्दूकस किया हुआ","100 ग्राम गाजर, बारीक कद्दूकस की हुई","500 ग्राम दुबला बीफ़ कीमा (5% वसा)","6 साबुत गेहूँ के बन (प्रत्येक 60 ग्राम)","1 लिटिल जेम लेट्यूस","1 लाल प्याज़, पतला कटा हुआ","3 टमाटर, कटे हुए"],
["ब्रेड को काली मिर्च और लहसुन के साथ कटोरे में चूरा करें। अंडा डालें और मिलाएँ, दो मिनट तक भीगने दें, फिर दोबारा मिलाएँ।","कद्दूकस किया प्याज़ और गाजर, और बीफ़ कीमा डालें। अच्छी तरह मिलाएँ, फिर मिश्रण को छह भागों में बाँटें।","अपने हाथ गीले करें और हर हिस्से को गोल गेंद का आकार दें, फिर उसे लगभग 2 सेमी मोटे बर्गर के आकार में चपटा करें। ढककर कम से कम 20 मिनट के लिए ठंडा होने के लिए फ्रिज में रखें।","नॉन-स्टिक पैन गरम करें, बर्गर डालें और 3-4 मिनट तक छोड़ दें, फिर स्पैचुला से पलटें और 3-4 मिनट और पकाएँ। (बर्गर को बहुत जल्दी पलटने से वे टूट सकते हैं)","जब आप सुनिश्चित कर लें कि बर्गर अंदर तक अच्छी तरह पक गए हैं, तो उन्हें बन में लेट्यूस, प्याज़ और टमाटर के स्लाइस के साथ परोसें।"],
["अतिरिक्त चटपटेपन के लिए, बर्गर के मिश्रण में कुछ चिली फ्लेक्स या 2 छोटे चम्मच स्मोक्ड पेपरिका डालें।","आप ये बर्गर टर्की, हिरण के मांस या दुबले भेड़ के कीमे से बना सकते हैं।","फ्रीज़ करने के निर्देश: कच्चे या पके, दोनों रूपों में फ्रीज़ किए जा सकते हैं। हर बर्गर के बीच ग्रीसप्रूफ़ पेपर रखकर अलग-अलग लपेटे हुए हिस्सों में फ्रीज़ करें। फ्रिज में या माइक्रोवेव में पूरी तरह पिघलाएँ, फिर पूरी तरह भाप निकलने तक और अंदर तक पकने तक अच्छी तरह गरम करें।",FV(1)]))
r.append(R(7333382,"भुने लहसुन और मशरूम का सूप","भुने लहसुन और ढेर सारी जड़ी-बूटियों के साथ मशरूम का एक स्वादिष्ट मिश्रण।","4","423 ग्राम",
["4 साबुत लहसुन के गुच्छे, बिना छिले और ऊपरी सिरे कटे हुए","2 छोटे चम्मच रेपसीड तेल","1 बड़ा प्याज़, कटा हुआ","2 बड़े पोर्टोबेलो मशरूम, कटे हुए (150 ग्राम)","200 ग्राम क्लोज़्ड कप मशरूम, कटे हुए","500 मिलीलीटर पानी में 1 कम नमक वाला वेजिटेबल स्टॉक क्यूब","एक अच्छी चुटकी सफ़ेद मिर्च","आधा छोटा चम्मच सूखा थाइम","1 x 400 ग्राम का डिब्बा कैनेलिनी बीन्स, छनी हुई","100 मिलीलीटर स्किम्ड दूध","150 ग्राम मिले-जुले विदेशी या जंगली मशरूम","3 बड़े चम्मच 0% वसा वाला ग्रीक शैली का दही","स्वाद अनुसार काली मिर्च","परोसने के लिए ताज़ा थाइम की पत्तियाँ (वैकल्पिक)"],
["लहसुन को किचन फ़ॉइल के एक चौकोर टुकड़े पर रखें और उस पर एक छोटा चम्मच तेल रगड़ें। पैकेट की तरह मोड़ें और ओवन में 190°C/गैस मार्क 5 पर 30-35 मिनट तक बेक करें।","बचा हुआ तेल पैन में डालें, फिर प्याज़ डालें और 5-6 मिनट तक नियमित रूप से चलाते हुए भूरा होने तक पकाएँ।","इसके बाद, कटे हुए कप और पोर्टोबेलो मशरूम डालें, फिर नरम होने तक 5 मिनट और पकाते रहें। स्टॉक, काली मिर्च और सूखा थाइम डालें, अच्छी तरह मिलाएँ, उबाल लाएँ, फिर आँच कम करें। ढक्कन लगाएँ और 5 मिनट तक हल्की आँच पर पकाएँ।","लहसुन को छिलके से निचोड़कर निकालें और कैनेलिनी बीन्स के साथ सॉसपैन में डालें और वापस उबाल लाएँ। दूध डालें, ब्लेंड करें और अलग रख लें।","इस बीच, जंगली मशरूम को नॉन-स्टिक पैन में 3-4 मिनट तक भूनें और अलग रख लें।","सूप में दही डालें, अच्छी तरह ब्लेंड करें, फिर 4 कटोरों में बाँट दें। ऊपर से भुने हुए जंगली मशरूम, भरपूर पिसी काली मिर्च और ताज़ा थाइम की पत्तियाँ डालें।"],
["आप इस सूप के लिए मशरूम के किसी भी मेल का इस्तेमाल कर सकते हैं। यह बटर बीन्स जैसी दूसरी बीन्स के साथ भी अच्छा बनता है।","थाइम की जगह तुलसी या ऑरिगैनो के साथ आज़माएँ।","लहसुन को भूनने से वह बहुत हल्का और मीठा हो जाता है, इसलिए आप जितनी मात्रा इस्तेमाल कर रहे हैं उससे हिचकिचाएँ नहीं।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रीज़ करने से पहले भुने हुए मशरूम मिलाएँ। माइक्रोवेव में या बहुत धीमी आँच पर पूरी तरह भाप निकलने तक गरम होने तक पिघलाएँ।",FV(1)]))
r.append(R(7334595,"पावर पोरिज","इस सरल पोरिज के साथ धीरे-धीरे ऊर्जा देने वाले कार्बोहाइड्रेट और भरपूर फ़ाइबर के साथ अपने दिन की शुरुआत करें।","2","341 ग्राम",
["30 ग्राम रोल्ड ओट्स","30 ग्राम कुट्टू (बकव्हीट) के फ्लेक्स","30 ग्राम क्विनोआ फ्लेक्स","400 मिलीलीटर पानी","1-2 छोटे चम्मच दानेदार स्वीटनर, अगर चाहें","160 ग्राम जमी हुई मिली-जुली बेरी, पिघलाई हुई","10 ग्राम सूरजमुखी के बीज, भुने हुए","10 ग्राम बादाम के फ्लेक्स","10 ग्राम कद्दू के बीज","50 मिलीलीटर स्किम्ड दूध, परोसने के लिए (वैकल्पिक)"],
["ओट्स, कुट्टू और क्विनोआ फ्लेक्स को एक छोटे पैन में डालें, पानी से ढकें, स्वीटनर डालें (अगर इस्तेमाल कर रहे हैं), और फिर धीमी आँच पर रखें। 3-4 मिनट तक पकाएँ।","पोरिज को 2 कटोरों में बाँटें, और ऊपर से बेरी और भुने हुए बीज डालें। अगर चाहें तो दूध के साथ परोसें।"],
[FV(1)]))
r.append(R(7335144,"तोरी, मिर्च और टमाटर के साथ स्पेगेटी","स्वाद से भरपूर एक झटपट वीगन पास्ता व्यंजन।","3","215 ग्राम",
["225 ग्राम साबुत गेहूँ की स्पेगेटी","1 छोटा चम्मच रेपसीड तेल","1 तोरी, लंबाई में चार भागों में कटी हुई, फिर कटी हुई","1 लहसुन की फांक, कुचली हुई","1 लाल मिर्च, बारीक कटी हुई","300 मिलीलीटर पासाटा (छनी हुई टमाटर प्यूरी)","2 बड़े चम्मच कटा हुआ ताज़ा अजमोद (पार्सले)"],
["पास्ता को पैकेट के निर्देशों के अनुसार पकाएँ। पानी निकालकर वापस पैन में डालें।","इस बीच, नॉन-स्टिक पैन में तेल गरम करें, तोरी, लहसुन और मिर्च डालें और 3-4 मिनट तक भूनें। पासाटा डालें, उबाल लाएँ और 5 मिनट तक हल्की आँच पर पकाएँ।","सॉस और अजमोद को पास्ता में मिलाएँ और परोसें।"],
["अगर आपके पास पासाटा नहीं है, तो एक बड़े चम्मच टमाटर प्यूरी के साथ डिब्बाबंद टमाटरों को गूदा बनने तक ब्लेंड करें।",FV(1)]))
r.append(R(7338005,"फलों वाला कोरोनेशन चिकन पिटा","यह गर्मियों के गरम दिनों में बढ़िया लंच बॉक्स बनता है।","2","367 ग्राम",
["2 छोटे चम्मच आधी वसा वाला क्रेम फ्रेश","4 छोटे चम्मच कम वसा वाला सादा दही","1 छोटा चम्मच मध्यम तीखा करी पाउडर","1 बड़ा चम्मच ताज़ा धनिया","1 बड़ा (200 ग्राम), बिना हड्डी और बिना त्वचा का चिकन ब्रेस्ट, पका हुआ और कटा हुआ","3 ताज़ी खुबानी, कटी हुई","1 आम, छीला और कटा हुआ (150 ग्राम)","3 हरी प्याज़ (स्प्रिंग अनियन), कटी हुई","60 ग्राम रॉकेट (अरुगुला) सलाद की पत्तियाँ","2 साबुत गेहूँ के पिटा (प्रत्येक 70 ग्राम)"],
["एक कटोरे में क्रेम फ्रेश, दही, करी पाउडर और धनिया मिलाएँ।","बाकी सामग्री मिलाएँ और कूसकूस, भुने हुए पिटा या अपनी पसंद की ब्रेड के साथ परोसें।"],
["बचे हुए रोस्ट चिकन का उपयोग करने के लिए आदर्श, या आप पहले से पके चिकन का एक हिस्सा खरीद सकते हैं।","अगर आपको तीखा खाना पसंद है, तो चुटकी भर चिली फ्लेक्स डालें।",FV(2)]))
r.append(R(7340829,"चीज़, प्याज़ और पालक के स्कोन","दोपहर की चाय के साथ स्वादिष्ट, या पिकनिक के लिए बढ़िया, इन्हें गरम या ठंडा खाया जा सकता है।","10","44 ग्राम",
["200 ग्राम साबुत गेहूँ का आटा","1 छोटा चम्मच बेकिंग पाउडर","एक अच्छी चुटकी सफ़ेद मिर्च","50 ग्राम पुराना कद्दूकस किया चेडर चीज़, 2 छोटे चम्मच बचाकर रखें","4 हरी प्याज़ (स्प्रिंग अनियन), बारीक कटी हुई","75 ग्राम जमा पालक, पिघलाया हुआ, अतिरिक्त पानी निचोड़ा हुआ, बारीक कटा हुआ (50 ग्राम मिलेगा)","2 बड़े चम्मच रेपसीड तेल","75 मिलीलीटर स्किम्ड दूध (ऊपर लगाने के लिए 1 बड़ा चम्मच बचाकर रखें)","आधा छोटा चम्मच पेपरिका (वैकल्पिक)"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें","फिर एक बड़ी बेकिंग शीट को ओवन में रखें।","आटा, बेकिंग पाउडर और काली मिर्च मिलाएँ, पालक और हरी प्याज़ डालें फिर कद्दूकस किया चीज़ मिश्रण में समान रूप से बाँटने के लिए छिड़कें।","मिश्रण के बीच में गड्ढा बनाएँ और तेल तथा आधा दूध डालें, मिलाएँ और बचा हुआ दूध तब तक मिलाएँ जब तक आपको नरम लेकिन सख़्त आटा न मिल जाए।","एक सतह पर हल्का आटा छिड़कें और आटे को धीरे से 2 सेमी मोटा बेलें। मध्यम कटर से स्कोन काटें और फिर गरम ओवन ट्रे पर रखें। किसी भी बचे हुए टुकड़ों को मिलाकर फिर से बेलें ताकि दो-चार स्कोन और मिल जाएँ।","ऊपरी हिस्सों पर अतिरिक्त दूध लगाएँ और हर स्कोन के ऊपर थोड़ा चीज़ और पेपरिका (अगर इस्तेमाल कर रहे हैं) छिड़कें।","12-15 मिनट तक सुनहरा भूरा होने तक बेक करें।"],
["स्कोन काटते समय कटर को घुमाने से बचें क्योंकि इससे वे अच्छी तरह फूलने से रुक सकते हैं।","आप अपनी पसंद का कोई भी चीज़ इस्तेमाल कर सकते हैं, यह रेसिपी बचे-खुचे चीज़ के टुकड़ों का उपयोग करने के लिए बढ़िया है।","ताज़ी तुलसी जैसी जड़ी-बूटियाँ या आधा छोटा चम्मच सूखा थाइम डालकर देखें","आधा काटकर थोड़ा कम वसा वाला क्रीम चीज़ लगाने और बारीक कटे खीरे और ताज़ी चाइव्स छिड़कने पर स्वादिष्ट।","फ्रीज़ करने के निर्देश: परोसने के लिए 2 घंटे तक पिघलाएँ, या माइक्रोवेव या मध्यम ओवन में पिघलाएँ/गरम करें।",FV(0)]))
save(6,r)
